import{_ as t,o as h,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Learner Context Model","description":"","frontmatter":{},"headers":[],"relativePath":"learner/context-model.md","filePath":"learner/context-model.md"}'),i={name:"learner/context-model.md"};function g(c,n,e,r,u,m){return h(),o("div",null,[...n[0]||(n[0]=[a('<h1 id="learner-context-model" tabindex="-1">Learner Context Model <a class="header-anchor" href="#learner-context-model" aria-label="Permalink to &quot;Learner Context Model&quot;">​</a></h1><p>Trên trang này# Learner Context Model <a href="#learner-context-model">​</a> Learner Model trả lời &quot;con biết gì&quot;. Context Model trả lời một câu hoàn toàn khác: <strong>&quot;đang có chuyện gì xảy ra với con lúc này?&quot;</strong> Hai learner có Learner Model giống hệt nhau vẫn nên nhận gợi ý khác nhau, nếu một em còn 18 tháng nữa mới thi và em kia còn 21 ngày. Không có gì trong kiến thức của hai em khác nhau — hoàn cảnh khác nhau.</p><h2 id="nhung-gi-đuoc-coi-la-context-​" tabindex="-1">Những gì được coi là context <a href="#nhung-gi-đuoc-coi-la-context">​</a> <a class="header-anchor" href="#nhung-gi-đuoc-coi-la-context-​" aria-label="Permalink to &quot;Những gì được coi là context [​](#nhung-gi-đuoc-coi-la-context)&quot;">​</a></h2><p>LoạiVí dụ<strong>Academic</strong>Kỳ thi học kỳ ngày 15/12; vừa chuyển trường<strong>Health</strong>Ốm ba ngày; đang hồi phục<strong>Emotional</strong>Căng thẳng với môn Hình; mất tự tin sau một bài kiểm tra<strong>Time</strong>Tuần này chỉ có 30 phút mỗi ngày; nghỉ hè, rảnh nhiều<strong>Family / Environment</strong>Nhà có việc; chuyển nhà; anh chị vừa thi xongĐây là những chuyện xảy ra <strong>quanh</strong> learner. Chúng không nói gì về việc con biết bao nhiêu, nhưng chúng quyết định rất nhiều về việc hôm nay nên làm gì.</p><h2 id="context-khong-bao-gio-lam-giam-muc-vung-​" tabindex="-1">Context không bao giờ làm giảm mức vững <a href="#context-khong-bao-gio-lam-giam-muc-vung">​</a> <a class="header-anchor" href="#context-khong-bao-gio-lam-giam-muc-vung-​" aria-label="Permalink to &quot;Context không bao giờ làm giảm mức vững [​](#context-khong-bao-gio-lam-giam-muc-vung)&quot;">​</a></h2><p>Quy tắc này nghe đơn giản nhưng là ranh giới bảo vệ toàn bộ hệ thống khỏi kết luận sai. Con ốm và làm bài kém trong tuần đó — Nemo12 <strong>không</strong> hạ Learner Model. Việc ốm nằm ở Context Model, và nó làm hai chuyện: giảm khối lượng đề xuất trong những ngày đó, và đánh dấu rằng bằng chứng thu được trong giai đoạn này cần được đọc thận trọng. Sau khi khỏi, không có gì phải &quot;phục hồi&quot;, vì không có gì bị hạ. So sánh với cách làm thông thường — điểm kém tuần ốm bị trộn thẳng vào đánh giá năng lực — thì khác biệt rất lớn: ba tháng sau vẫn còn nguyên một vết lõm không ai giải thích được trên biểu đồ.</p><h2 id="moi-thong-tin-đeu-mang-nguon-va-đo-tin-cay-​" tabindex="-1">Mỗi thông tin đều mang nguồn và độ tin cậy <a href="#moi-thong-tin-đeu-mang-nguon-va-đo-tin-cay">​</a> <a class="header-anchor" href="#moi-thong-tin-đeu-mang-nguon-va-đo-tin-cay-​" aria-label="Permalink to &quot;Mỗi thông tin đều mang nguồn và độ tin cậy [​](#moi-thong-tin-đeu-mang-nguon-va-đo-tin-cay)&quot;">​</a></h2><p>Không phải thông tin nào cũng đáng tin như nhau, nên mỗi mẩu context đi kèm hai thứ: ai nói, và tin được tới đâu. text&quot;Căng thẳng với Hình học · mức CAO · learner tự nói · 0.90&quot; &quot;Căng thẳng với Hình học · mức TRUNG BÌNH · hệ thống suy đoán · 0.52&quot;Dòng đầu là con tự nói ra. Dòng sau là hệ thống suy ra từ hành vi — bỏ dở nhiều bài Hình, thời gian phản hồi dài bất thường. Cả hai đều có ích, nhưng chúng <strong>không được đối xử như nhau</strong>, và cái thứ hai không bao giờ được trình bày với gia đình như một sự thật.</p><h2 id="khong-context-nao-ton-tai-mai-mai-​" tabindex="-1">Không context nào tồn tại mãi mãi <a href="#khong-context-nao-ton-tai-mai-mai">​</a> <a class="header-anchor" href="#khong-context-nao-ton-tai-mai-mai-​" aria-label="Permalink to &quot;Không context nào tồn tại mãi mãi [​](#khong-context-nao-ton-tai-mai-mai)&quot;">​</a></h2><p>Mỗi mẩu context có hạn sử dụng. Một đợt ốm tự hết hiệu lực sau vài ngày nếu không ai xác nhận là vẫn còn. Một kỳ thi qua rồi thì thôi. Sự căng thẳng ba tháng trước không được phép tiếp tục định hình gợi ý hôm nay. Ba trạng thái của một mẩu context:</p><ul><li><strong>Đang có hiệu lực</strong> — vẫn đúng lúc này.</li><li><strong>Đã kết thúc</strong> — có người xác nhận (&quot;con khỏi rồi&quot;).</li><li><strong>Hết hạn</strong> — quá thời gian mà không ai nhắc lại; hệ thống tự gỡ. Trạng thái thứ ba quan trọng hơn vẻ ngoài của nó. Không có nó, hồ sơ context của một đứa trẻ sẽ chất đống thành một danh sách vấn đề vĩnh viễn — điều gần như luôn xảy ra với các hệ thống ghi chú giáo dục.</li></ul><h2 id="sua-thong-tin-bang-cach-ghi-them-khong-xoa-đi-​" tabindex="-1">Sửa thông tin bằng cách ghi thêm, không xoá đi <a href="#sua-thong-tin-bang-cach-ghi-them-khong-xoa-đi">​</a> <a class="header-anchor" href="#sua-thong-tin-bang-cach-ghi-them-khong-xoa-đi-​" aria-label="Permalink to &quot;Sửa thông tin bằng cách ghi thêm, không xoá đi [​](#sua-thong-tin-bang-cach-ghi-them-khong-xoa-đi)&quot;">​</a></h2><p>Khi lịch thi đổi, hệ thống không sửa đè lên bản ghi cũ. Nó ghi một sự kiện mới: <em>&quot;kỳ thi dời từ 15/12 sang 22/12, thay thế cho bản ghi trước&quot;</em>. Nhờ vậy luôn trả lời được câu hỏi <em>&quot;tuần trước hệ thống nghĩ gì mà lại gợi ý như thế?&quot;</em>. Một hệ thống sửa đè lên chính mình thì mọi quyết định quá khứ của nó đều không giải thích được nữa.</p><h2 id="context-vao-he-thong-bang-cach-nao-​" tabindex="-1">Context vào hệ thống bằng cách nào <a href="#context-vao-he-thong-bang-cach-nao">​</a> <a class="header-anchor" href="#context-vao-he-thong-bang-cach-nao-​" aria-label="Permalink to &quot;Context vào hệ thống bằng cách nào [​](#context-vao-he-thong-bang-cach-nao)&quot;">​</a></h2><p>Chủ yếu bằng cách <strong>nói chuyện bình thường</strong>. Phụ huynh nhắn &quot;tuần này con ốm, cho học nhẹ thôi&quot;; learner viết &quot;con sợ phần hình&quot;. Hệ thống hiểu câu đó, <strong>hỏi lại để xác nhận</strong>, rồi mới ghi. Nemo12 cố tình không dùng biểu mẫu 20 ô để thu thập context. Không gia đình nào điền form đó lần thứ hai, và một context không được cập nhật thì tệ hơn không có — vì nó khiến hệ thống tự tin dựa trên thứ đã cũ. Khi nào bạn nên chủ động báo context Khi có gì đó thật sự đổi trong vài tuần tới: kỳ thi, chuyến đi, đợt ốm, một giai đoạn bận. Bạn không cần báo gì về việc con học thế nào — phần đó hệ thống tự quan sát. Cùng một đứa trẻ, cùng một mức kiến thức, nhưng hoàn cảnh khác thì việc nên làm hôm nay cũng khác. Đó là toàn bộ lý do Context Model tồn tại. <a href="/learner/evidence">Evidence →</a></p>',15)])])}const x=t(i,[["render",g]]);export{s as __pageData,x as default};
